package com.backend_core.recruforce2.domain.entities;

import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDateTime;

/**
 * Stores the result of an AI prediction for a candidate/job offer pair.
 * Generated by the Python AI microservice (recruforce2-ai-model).
 */
@Entity
@Table(name = "predictions", indexes = {
  @Index(name = "idx_predictions_candidate_id", columnList = "candidate_id"),
  @Index(name = "idx_predictions_job_offer_id", columnList = "job_offer_id"),
  @Index(name = "idx_predictions_created_at", columnList = "created_at")
})
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class Prediction {

  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;

  /** The candidate evaluated */
  @ManyToOne(fetch = FetchType.LAZY)
  @JoinColumn(name = "candidate_id", nullable = false)
  private Candidate candidate;

  /** The job offer the candidate is evaluated against */
  @ManyToOne(fetch = FetchType.LAZY)
  @JoinColumn(name = "job_offer_id", nullable = false)
  private JobOffer jobOffer;

  /**
   * Matching score between the candidate profile and the job offer.
   * Range: 0.0 to 100.0
   */
  @Column(name = "matching_score")
  private Double matchingScore;

  /**
   * Predicted probability of successful integration.
   * Range: 0.0 to 1.0
   */
  @Column(name = "success_probability")
  private Double successProbability;

  /**
   * AI confidence level in this prediction.
   * Range: 0.0 to 1.0
   */
  @Column
  private Double confidence;

  /** JSON-serialized key factors that influenced the prediction score */
  @Column(name = "main_factors", columnDefinition = "TEXT")
  private String mainFactors;

  /** Human-readable recommendation generated by the AI model */
  @Column(columnDefinition = "TEXT")
  private String recommendation;

  /** Date and time this prediction was calculated */
  @Column(name = "calculated_at", nullable = false, updatable = false)
  private LocalDateTime calculatedAt;

  /** The ML model version that generated this prediction */
  @Column(name = "model_version", length = 20)
  private String modelVersion;

  /** The ML model entity that generated this prediction */
  @ManyToOne(fetch = FetchType.LAZY)
  @JoinColumn(name = "ml_model_id")
  private MLModel model;

  // -------------------------------------------------------
  // Lifecycle hooks
  // -------------------------------------------------------

  @PrePersist
  protected void onCreate() {
    this.calculatedAt = LocalDateTime.now();
  }

  // -------------------------------------------------------
  // Business methods
  // -------------------------------------------------------

  /** Calculates and stores the prediction result from the AI microservice */
  public void calculate(Double matchingScore, Double successProbability,
                        Double confidence, String mainFactors, String recommendation) {
    this.matchingScore = matchingScore;
    this.successProbability = successProbability;
    this.confidence = confidence;
    this.mainFactors = mainFactors;
    this.recommendation = recommendation;
  }

  /**
   * Returns a human-readable explanation of this prediction.
   * Summarizes the main factors and recommendation.
   */
  public String explain() {
    return String.format(
      "Candidate %s scored %.1f%% match for offer '%s'. " +
        "Success probability: %.0f%%. Confidence: %.0f%%. Recommendation: %s",
      candidate.getFullName(),
      matchingScore,
      jobOffer.getTitle(),
      successProbability != null ? successProbability * 100 : 0,
      confidence != null ? confidence * 100 : 0,
      recommendation
    );
  }
}
